<?php
function renderTableCard(array $table): void { $status=$table['status']; $classes=['available'=>'border-green-500/40','running'=>'border-red-500/60','paused'=>'border-amber-500/60','held'=>'border-orange-500/60','closed'=>'border-slate-600']; $badge=['available'=>'bg-green-500/20 text-green-400','running'=>'bg-red-500/20 text-red-400','paused'=>'bg-amber-500/20 text-amber-400','held'=>'bg-orange-500/20 text-orange-400','closed'=>'bg-slate-500/20 text-slate-400']; ?>
<article class="table-card bg-slate-800 border <?=$classes[$status]??'border-slate-700'?> rounded-xl p-4 min-h-60 flex flex-col" id="table-<?=$table['id']?>" data-table-id="<?=$table['id']?>" data-rate-plan="<?=$table['rate_plan_id']??''?>"><div class="flex justify-between items-start"><div><div class="text-5xl font-extrabold leading-none"><?=sanitize($table['table_number'])?></div><div class="mt-2 text-xs text-slate-400 uppercase tracking-widest"><?=sanitize($table['table_type'])?></div></div><span class="status inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs uppercase font-bold <?=$badge[$status]??''?>"><?= $status==='running'?'<i class="fa-solid fa-circle text-[7px] animate-pulse"></i>':'' ?><?=sanitize($status)?></span></div><div class="table-detail flex-1 mt-5"><?php if(in_array($status,['running','paused'])): ?><div class="player font-semibold truncate"><?=sanitize($table['player_name']?:'Walk-in Guest')?></div><div class="timer font-mono text-2xl mt-2 <?=$status==='running'?'text-green-400':'text-amber-400'?>" data-start="<?=strtotime($table['start_time']??'now')?>" data-paused="<?=$table['total_pause_seconds']??0?>">00:00:00</div><div class="amount text-xl font-bold mt-1"><?=money(($table['display_amount']??0)+($table['cafe_amount']??0))?></div><?php elseif($status==='held'): ?><div class="text-slate-400 mt-6">Held bill</div><div class="amount text-xl font-bold mt-1"><?=money($table['display_amount']??0)?></div><?php elseif($status==='available'): ?><button class="start-session w-full mt-8 py-3 text-green-400 border border-green-500/40 rounded-lg hover:bg-green-500/10"><i class="fa-solid fa-play mr-2"></i>Tap to Start</button><?php else: ?><div class="text-slate-500 mt-8 text-center">Closed for maintenance</div><?php endif; ?></div><div class="actions flex gap-2 mt-3"><?php if($status==='running'): ?><button class="cafe-btn btn-secondary flex-1"><i class="fa-solid fa-mug-hot"></i> Café</button><button class="pause-btn btn-secondary" title="Pause"><i class="fa-solid fa-pause"></i></button><button class="hold-btn btn-secondary" title="Hold bill"><i class="fa-solid fa-hand"></i></button><button class="end-btn btn-danger" title="End & bill"><i class="fa-solid fa-stop"></i></button><?php elseif($status==='paused'): ?><button class="resume-btn btn-primary flex-1"><i class="fa-solid fa-play"></i> Resume</button><button class="end-btn btn-danger"><i class="fa-solid fa-stop"></i></button><?php elseif($status==='held'): ?><button class="recall-btn btn-primary w-full"><i class="fa-solid fa-reply"></i> Recall Bill</button><?php endif; ?></div></article><?php }
